<script setup>
import {ref,watch} from 'vue';import {Head,useForm,router,Link} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({users:Object,search:String});const query=ref(props.search||'');let timeout;
watch(query,v=>{clearTimeout(timeout);timeout=setTimeout(()=>router.get('/users',{search:v},{preserveState:true,replace:true}),350)});
const form=useForm({name:'',email:'',password:'',role:'student'});
const create=()=>form.post('/users',{onSuccess:()=>form.reset()});
const toggle=u=>{if(!confirm((u.is_active?'Khóa':'Mở khóa')+' tài khoản '+u.email+'?'))return;router.put('/users/'+u.id,{name:u.name,role:u.role,is_active:!u.is_active});};
</script>
<template><Head title="Tài khoản"/><AppLayout><h1>Quản lý tài khoản</h1><div class="card"><h2>Tạo tài khoản</h2><form @submit.prevent="create" class="formgrid"><div class="field"><label>Họ tên</label><input v-model="form.name" required/><small class="error">{{form.errors.name}}</small></div><div class="field"><label>Email</label><input v-model="form.email" type="email" required/><small class="error">{{form.errors.email}}</small></div><div class="field"><label>Mật khẩu (ít nhất 12 ký tự)</label><input v-model="form.password" type="password" minlength="12" required/><small class="error">{{form.errors.password}}</small></div><div class="field"><label>Vai trò</label><select v-model="form.role"><option value="student">Thí sinh</option><option value="teacher">Giáo viên</option><option value="admin">Admin</option></select></div><button :disabled="form.processing">Tạo tài khoản</button></form></div><div class="card" style="margin-top:20px"><h2>Danh sách tài khoản</h2><div class="field"><input v-model="query" placeholder="Tìm theo tên hoặc email..."/></div><div class="tablewrap"><table><thead><tr><th>Tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="u in users.data" :key="u.id"><td>{{u.name}}</td><td>{{u.email}}</td><td>{{u.role}}</td><td><span class="pill">{{u.is_active?'Đang hoạt động':'Đã khóa'}}</span></td><td><button class="secondary" @click="toggle(u)">{{u.is_active?'Khóa':'Mở khóa'}}</button></td></tr></tbody></table></div><div class="pagination"><Link v-if="users.prev_page_url" :href="users.prev_page_url">← Trước</Link><span>Trang {{users.current_page}} / {{users.last_page}}</span><Link v-if="users.next_page_url" :href="users.next_page_url">Tiếp →</Link></div></div></AppLayout></template>
